import{_ as s,o as t,c as a,a4 as i}from"./chunks/framework.DzJZdBQK.js";const c=JSON.parse('{"title":"IPFS私有网络","description":"","frontmatter":{"date":"2018-08-09T22:53:13","title":"IPFS私有网络","categories":["ipfs"],"tags":["ipfs","private network"]},"headers":[{"level":2,"title":"私有网络（Private Networks）","slug":"私有网络-private-networks","link":"#私有网络-private-networks","children":[]},{"level":2,"title":"状态（State）","slug":"状态-state","link":"#状态-state","children":[]},{"level":2,"title":"In Version","slug":"in-version","link":"#in-version","children":[]},{"level":2,"title":"如何启用（How to enable）","slug":"如何启用-how-to-enable","link":"#如何启用-how-to-enable","children":[]},{"level":2,"title":"参考链接","slug":"参考链接","link":"#参考链接","children":[]}],"relativePath":"posts/ipfs/ipfs-1.md","filePath":"posts/ipfs/ipfs-1.md"}'),n={name:"posts/ipfs/ipfs-1.md"};function p(r,e,o,l,h,k){return t(),a("div",null,[...e[0]||(e[0]=[i(`<p>本文来源<a href="https://github.com/ipfs/go-ipfs/blob/master/docs/experimental-features.md#private-networks" target="_blank" rel="noreferrer">Private Networks</a></p><h2 id="私有网络-private-networks" tabindex="-1">私有网络（Private Networks） <a class="header-anchor" href="#私有网络-private-networks" aria-label="Permalink to &quot;私有网络（Private Networks）&quot;">​</a></h2><p>Allows ipfs to only connect to other peers who have a shared secret key.</p><p>IPFS只有共享密钥的节点才可互相连接。</p><h2 id="状态-state" tabindex="-1">状态（State） <a class="header-anchor" href="#状态-state" aria-label="Permalink to &quot;状态（State）&quot;">​</a></h2><p>Experimental</p><p>实验性</p><h2 id="in-version" tabindex="-1">In Version <a class="header-anchor" href="#in-version" aria-label="Permalink to &quot;In Version&quot;">​</a></h2><p>master, 0.4.7</p><h2 id="如何启用-how-to-enable" tabindex="-1">如何启用（How to enable） <a class="header-anchor" href="#如何启用-how-to-enable" aria-label="Permalink to &quot;如何启用（How to enable）&quot;">​</a></h2><p>Generate a pre-shared-key using <a href="https://github.com/Kubuxu/go-ipfs-swarm-key-gen" target="_blank" rel="noreferrer">ipfs-swarm-key-gen</a>:</p><p>通过<a href="https://github.com/Kubuxu/go-ipfs-swarm-key-gen" target="_blank" rel="noreferrer">ipfs-swarm-key-gen</a>生成一个共享密钥：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/Kubuxu/go-ipfs-swarm-key-gen/ipfs-swarm-key-gen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipfs-swarm-key-gen</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ipfs/swarm.key</span></span></code></pre></div><p>To join a given private network, get the key file from someone in the network and save it to ~/.ipfs/swarm.key (If you are using a custom $IPFS_PATH, put it in there instead).</p><p>加入私有网络，需要从网络中的其他人中获取密钥文件并把它保存为<code>~/.ipfs/swarm.key</code>（如果你设置了$IPFS_PATH，替换为设置的目录）。</p><p>When using this feature, you will not be able to connect to the default bootstrap nodes (Since we aren&#39;t part of your private network) so you will need to set up your own bootstrap nodes.</p><p>当你使用这个功能的时候，你不可以使用默认的启动节点（因为不是私有网络的一部分），因此你需要设置你自己的启动节点。</p><p>First, to prevent your node from even trying to connect to the default bootstrap nodes, run:</p><p>首先为了防止你的节点尝试连接默认的启动节点，你需要运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span></span></code></pre></div><p><strong>注意，这里有个BUG，可能会导致当前节点也被移除，而启动错误，需要手动重新添加。</strong></p><p>Then add your own bootstrap peers with:</p><p>然后添加你自己的启动节点</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">multiadd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>For example:</p><p>例如：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bootstrap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /ip4/104.236.76.40/tcp/4001/ipfs/QmSoLV4Bbm51jM9C4gDYZQ9Cy3U6aXMJDAbzgu2fzaDs64</span></span></code></pre></div><p>Bootstrap nodes are no different from all other nodes in the network apart from the function they serve.</p><p>除了提供启动功能外，启动节点和网络中的其他节点没有什么不同。</p><p>To be extra cautious, You can also set the LIBP2P_FORCE_PNET environment variable to 1 to force the usage of private networks. If no private network is configured, the daemon will fail to start.</p><p>为了更安全，你也可以设置LIBP2P_FORCE_PNET环境变量为1来强制使用私用网络。如果没有配置私有网络，ipfs守护进程就会无法启动。</p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><p><a href="https://zhuanlan.zhihu.com/p/35141862" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/35141862</a></p>`,33)])])}const g=s(n,[["render",p]]);export{c as __pageData,g as default};
